import {treasures,treasureCatalog,inscription,fourLoves} from './treasure-data.js';
import {esc,photoCredit} from './study-data.js';
import {Magnifier} from './magnifier.js';
import {DrumAudio} from './treasure-audio.js';
const root=document.getElementById('treasure-root'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let archive=[],current=null,lens=null,cleanup=()=>{},step=0,answered=new Set();
const merged=t=>({...archive.find(a=>a.id===t.id),...t,displayImage:t.image||archive.find(a=>a.id===t.id)?.displayImage});
const href=t=>t.type==='chimes'?'chimes/':'treasures.html?treasure='+encodeURIComponent(t.id);
function gallery(){cleanup();lens?.destroy();lens=null;current=null;document.title='镇馆之宝 · 大江大湖间的符号——色彩与文化记忆';root.innerHTML=`<section class="treasure-intro"><div><span class="eyebrow">THE TREASURES / 湖北省博物馆</span><h1>让珍藏，与你相遇。</h1><p>循一段铭文，听一声回响。<br>十件镇馆之宝，十种走近历史的方式。</p></div><span class="collection-count">10<small>镇馆之宝 / 交互展厅</small></span></section><section class="treasure-grid" aria-label="十件镇馆之宝">${treasures.map((t,i)=>{const a=merged(t);return `<a class="treasure-card card-${t.type} ${i<2?'large':''}" href="${href(t)}"><span class="card-number">${t.number}<i> / </i>${esc(t.tag)}</span><div class="card-photo"><img src="${esc(a.displayImage)}" alt="${esc(t.title)}" ${i>2?'loading="lazy"':''}></div><div class="card-copy"><span>${esc(t.title)}</span><h2>${esc(t.name)}</h2><p>${esc(t.intro)}</p><strong>进入体验 <i>↗</i></strong></div></a>`}).join('')}</section><footer class="treasure-colophon"><span>每一次探索，都从器物本身出发。</span><a href="${treasureCatalog}" target="_blank" rel="noopener">湖北省博物馆 · 镇馆之宝目录 ↗</a><p>互动根据馆方记录设计。角色视角为现代导览，鼓声为合成示意；照片与模型的资料说明见逐件体验。</p></footer>`}
function navigate(id,push=true){const t=treasures.find(t=>t.id===id);if(!t){gallery();return}if(t.type==='chimes'){location.assign('chimes/');return}if(push)history.pushState({},'',href(t));cleanup();lens?.destroy();lens=null;current=merged(t);step=0;answered=new Set();document.title=t.title+' · 珍藏互动 · 大江大湖间的符号——色彩与文化记忆';renderRoom();window.scrollTo({top:0,behavior:'instant'})}
function renderRoom(){const a=current;root.innerHTML=`<section class="room-title"><a href="treasures.html" data-gallery>← 十件珍藏</a><div><span class="eyebrow">${a.number} / ${esc(a.tag)}</span><h1>${esc(a.name)}</h1><p>${esc(a.title)}<i> / </i>${esc(a.period||'馆藏档案')}</p></div><span class="room-seal">${a.type.includes('drum')?'声':a.type==='sword'?'铭':'观'}</span></section><section class="treasure-room room-${a.type}"><div class="room-visual"><div class="treasure-photo"><img src="${esc(a.displayImage)}" alt="${esc(a.title)}"><div class="observation-light"></div><span class="photo-coordinate">COLLECTION ${a.number}<br>${esc(a.title)}</span>${a.type.includes('drum')?'<button class="drum-target" aria-label="敲击鼓面"><span>敲</span><i></i></button>':''}</div><div class="room-photo-note">${photoCredit(a)||'<a href="'+esc(a.source)+'" target="_blank" rel="noopener">图片 · 湖北省博物馆 ↗</a>'}</div><div class="room-lens-head"><span>局部观察</span><small>拖动细看 · 滚轮放大</small></div><div class="room-lens-view"></div></div><div class="room-reading"><nav class="chapter-nav" aria-label="探索章节">${a.chapters.map((c,i)=>`<button data-chapter="${i}" aria-pressed="${i===0}"><small>${String(i+1).padStart(2,'0')}</small>${esc(c.name)}</button>`).join('')}</nav><article class="chapter-copy" aria-live="polite"></article><div class="room-interaction"></div><div class="room-links">${archive.some(x=>x.id===a.id)?`<a href="object.html?id=${a.id}">完整器物档案 ↗</a><a href="index.html?view=particles&object=${a.id}">召唤这件器物的点云 ↗</a>`:''}<a href="${esc(a.source)}" target="_blank" rel="noopener">阅读馆方原始记录 ↗</a></div><p class="room-basis">${a.type==='sword'?'角色为观看视角；情境提示不代表具体历史人物真实言行。':a.type.includes('drum')?'设计音色用于感受节奏；不是文物录音或古代音响的复原。':'互动为辅助观察；放大照片不会补出未拍到的细节。'}</p></div></section>`;
 lens=new Magnifier(root.querySelector('.room-lens-view'),{src:a.displayImage,rect:a.chapters[0].rect,label:a.title+'局部观察'});showChapter(0);setupInteraction();
 const photo=root.querySelector('.treasure-photo');if(a.type==='light'){photo.classList.add('has-light');photo.addEventListener('pointermove',e=>{const r=photo.getBoundingClientRect();photo.style.setProperty('--lx',`${(e.clientX-r.left)/r.width*100}%`);photo.style.setProperty('--ly',`${(e.clientY-r.top)/r.height*100}%`)})}
}
function showChapter(i){step=i;const c=current.chapters[i];root.querySelectorAll('[data-chapter]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.chapter===i));root.querySelector('.chapter-copy').innerHTML=`<span class="eyebrow">${esc(c.kicker||'LOOK CLOSER / 细看')}</span><h2>${esc(c.title)}</h2><p>${esc(c.text)}</p>${c.task?`<div class="evidence-question"><strong>${esc(c.task)}</strong><div>${c.answers.map((answer,n)=>`<button data-answer="${n}">${esc(answer)}</button>`).join('')}</div><p class="answer-feedback" role="status">${answered.has(i)?esc(c.feedback):'选择一项，查看它与记录的关系。'}</p></div>`:''}`;const src=current.id==='hb-4694'?(i===1?'treasure-assets/sword-detail.jpg':'treasure-assets/sword-wide.jpg'):current.displayImage;
 const rect=current.id==='hb-4694'?(i===0?[.22,.40,.58,.35]:i===1?[.37,.34,.29,.30]:[0,0,1,1]):c.rect;
 if(lens?.src!==src){lens?.destroy();lens=new Magnifier(root.querySelector('.room-lens-view'),{src,rect,label:current.title+'局部观察'})}else lens?.setRect(rect);
 if(current.id==='hb-4694'&&!root.querySelector('.lens-credit'))root.querySelector('.room-lens-view').insertAdjacentHTML('afterend','<p class="lens-credit">细节实拍：Siyuwj · <a href="https://commons.wikimedia.org/wiki/Category:Sword_of_Goujian" target="_blank" rel="noopener">Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank">CC BY-SA 4.0</a> · 仅在观察窗裁切显示</p>');
 root.querySelector('.room-lens-head span').textContent=c.name+' · 局部观察'}
function setupInteraction(){const host=root.querySelector('.room-interaction'),a=current;
 if(a.type.includes('drum')){setupDrum(host,a.type==='bronze-drum'?'bronze':'skin');return}
 if(a.type==='sword'){host.innerHTML=`<h3>逐字释读</h3><p class="interaction-hint">点亮现代汉字，读出铭文的身份线索。</p><div class="inscription">${inscription.map((v,i)=>`<button data-inscription="${i}" aria-label="释读铭文第${i+1}字" aria-pressed="false"><small>${i+1}</small><span>·</span></button>`).join('')}</div><p class="inscription-readout" aria-live="polite">“越王”指身份，“鸠浅”指名，后四字说明自作用剑。</p><button class="reference-button" data-reference>查看剑身高清实拍 ↗</button><div class="reference-photo" hidden></div>`;host.querySelectorAll('[data-inscription]').forEach(b=>b.onclick=()=>{b.querySelector('span').textContent=inscription[+b.dataset.inscription];b.setAttribute('aria-pressed','true')});host.querySelector('[data-reference]').onclick=()=>{const box=host.querySelector('.reference-photo');box.hidden=!box.hidden;box.innerHTML='<a href="treasure-assets/sword-wide.jpg" target="_blank"><img src="treasure-assets/sword-wide.jpg" alt="越王勾践剑高清横向实拍，点击原图"></a><p>摄影 Siyuwj · <a href="https://commons.wikimedia.org/wiki/File:Sword_of_Goujian,_Hubei_Provincial_Museum,_2015-04-06_01-edit.jpg" target="_blank" rel="noopener">Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank">CC BY-SA 4.0</a> · 原图展示</p>'};return}
 if(a.type==='pairing'){let person=0,solved=new Set();host.innerHTML='<h3>为四爱，找到彼此</h3><div class="love-people">'+fourLoves.map(([p],i)=>`<button data-person="${i}" aria-pressed="${i===0}">${p}</button>`).join('')+'</div><div class="love-objects">'+['莲','梅与鹤','兰','菊'].map(v=>`<button data-love="${v}">${v}</button>`).join('')+'</div><p class="pair-feedback" role="status">先选择人物，再选择他所爱的事物。</p>';host.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{person=+b.dataset.person;host.querySelectorAll('[data-person]').forEach(x=>x.setAttribute('aria-pressed',x===b))});host.querySelectorAll('[data-love]').forEach(b=>b.onclick=()=>{const correct=b.dataset.love===fourLoves[person][1];if(correct){solved.add(person);host.querySelector(`[data-person="${person}"]`).classList.add('solved')}host.querySelector('.pair-feedback').textContent=correct?`${fourLoves[person][0]}爱${fourLoves[person][1]}。已配对 ${solved.size} / 4。`:'这一组尚不对应，试试另一种。'});return}
 if(a.type==='slips'){host.innerHTML='<div class="bamboo-desk" aria-label="秦简主题抽屉">'+['农业生产','市场交易','徭役征发'].map((v,i)=>`<button data-chapter="${i}" aria-pressed="${i===0}">${v}<small>馆方记载主题</small></button>`).join('')+'</div><p class="interaction-hint">这三支为现代主题索引，不是出土竹简的逐字摹本。</p>';return}
 if(a.type==='procession'){host.innerHTML='<h3>叙事行进</h3><div class="procession-steps">'+['出行','出行','猪犬','迎宾','迎宾'].map((v,i)=>`<button data-chapter="${i<2?0:i===2?1:2}" aria-label="第${i+1}画段：${v}"><small>${i+1}</small><span>${v}</span></button>`).join('')+'</div><p class="interaction-hint">按馆方文字描述导航；不是对缺失画面的自动补绘。</p>';return}
 host.innerHTML='<h3>留一点时间给细节</h3><p class="interaction-hint">选择上方观察位置，拖动左侧局部照片。原始分辨率有限的部分，保留它真实的清晰度。</p>';
}
function setupDrum(host,kind){
 const audio=new DrumAudio(kind),pattern=[2,0,1,0,2,1,0,3],names=['休止','轻敲','重敲','边击'];let playing=false,timer=null,nextTime=0,index=0,tempo=88,raf=0,queue=[];
 host.innerHTML=`<div class="drum-pads"><button data-strike="1">轻敲 <kbd>A</kbd></button><button data-strike="2">重敲 <kbd>S</kbd></button><button data-strike="3">边击 <kbd>D</kbd></button></div><h3>写一段八拍</h3><p class="interaction-hint">点按每一拍，在休止、轻敲、重敲、边击之间切换。</p><div class="beat-grid">${pattern.map((v,i)=>`<button data-beat="${i}" data-kind="${v}" aria-label="第${i+1}拍：${names[v]}"><small>${i+1}</small><span>${names[v]}</span></button>`).join('')}</div><div class="beat-transport"><button data-play aria-pressed="false">▶ 播放节奏</button><label>速度 <input type="range" min="48" max="160" value="88" aria-label="节奏速度"><output>88 BPM</output></label><button data-clear>清空</button></div><p class="audio-status" role="status">点击鼓面或按 A / S / D 发声。声音将在操作后启用。</p>`;
 const pulse=()=>{const target=root.querySelector('.drum-target');if(!target)return;target.classList.remove('struck');void target.offsetWidth;target.classList.add('struck')};
 const strike=async type=>{try{await audio.start();audio.strike(type);pulse();host.querySelector('.audio-status').textContent=`${kind==='bronze'?'金属':'鼓膜'}合成音色 · ${names[type]}`}catch{host.querySelector('.audio-status').textContent='浏览器暂时未能启动声音，请再次点击。'}};
 const stop=()=>{playing=false;clearInterval(timer);cancelAnimationFrame(raf);queue=[];audio.stop();host.querySelector('[data-play]').setAttribute('aria-pressed','false');host.querySelector('[data-play]').textContent='▶ 播放节奏';host.querySelectorAll('[data-beat]').forEach(b=>b.classList.remove('playing'))};
 const tick=()=>{while(nextTime<audio.context.currentTime+.12){const beat=index;if(pattern[beat])audio.strike(pattern[beat],nextTime);queue.push({time:nextTime,beat});nextTime+=60/tempo;index=(index+1)%8}};
 const frame=()=>{if(!playing)return;while(queue.length&&queue[0].time<=audio.context.currentTime){const {beat}=queue.shift();host.querySelectorAll('[data-beat]').forEach(b=>b.classList.toggle('playing',+b.dataset.beat===beat));if(pattern[beat])pulse()}raf=requestAnimationFrame(frame)};
 host.querySelectorAll('[data-strike]').forEach(b=>b.onclick=()=>strike(+b.dataset.strike));root.querySelector('.drum-target').onclick=()=>strike(2);host.querySelectorAll('[data-beat]').forEach(b=>b.onclick=()=>{const i=+b.dataset.beat;pattern[i]=(pattern[i]+1)%4;b.dataset.kind=pattern[i];b.querySelector('span').textContent=names[pattern[i]];b.setAttribute('aria-label',`第${i+1}拍：${names[pattern[i]]}`)});
 host.querySelector('[data-play]').onclick=async()=>{if(playing){stop();return}try{await audio.start();playing=true;index=0;nextTime=audio.context.currentTime+.06;host.querySelector('[data-play]').setAttribute('aria-pressed','true');host.querySelector('[data-play]').textContent='Ⅱ 暂停';tick();timer=setInterval(tick,25);frame()}catch{host.querySelector('.audio-status').textContent='音频未能启动，请再次点击。'}};
 host.querySelector('input').oninput=e=>{tempo=+e.target.value;host.querySelector('output').textContent=tempo+' BPM'};host.querySelector('[data-clear]').onclick=()=>{stop();pattern.fill(0);host.querySelectorAll('[data-beat]').forEach((b,i)=>{b.dataset.kind='0';b.querySelector('span').textContent='休止';b.setAttribute('aria-label',`第${i+1}拍：休止`)})};
 const key=e=>{if(e.repeat||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;const i=['a','s','d'].indexOf(e.key.toLowerCase());if(i>=0){e.preventDefault();strike(i+1)}};const visibility=()=>{if(document.hidden)stop()};document.addEventListener('keydown',key);document.addEventListener('visibilitychange',visibility);cleanup=()=>{stop();audio.dispose();document.removeEventListener('keydown',key);document.removeEventListener('visibilitychange',visibility);cleanup=()=>{}};
}
root.addEventListener('click',e=>{const card=e.target.closest('a[href^="treasures.html"]');if(card){e.preventDefault();const id=new URL(card.href).searchParams.get('treasure');if(id)navigate(id);else{history.pushState({},'','treasures.html');gallery();window.scrollTo(0,0)}return}const b=e.target.closest('button');if(!b)return;if(b.dataset.chapter!==undefined)showChapter(+b.dataset.chapter);if(b.dataset.answer!==undefined){const c=current.chapters[step],correct=+b.dataset.answer===c.correct;if(correct)answered.add(step);root.querySelector('.answer-feedback').textContent=correct?c.feedback:'这项没有得到当前记录支持。再回到器物和馆方说明中找一找。';b.classList.toggle('correct',correct)}});
window.addEventListener('popstate',()=>{const id=new URLSearchParams(location.search).get('treasure');id?navigate(id,false):gallery()});window.addEventListener('pagehide',()=>cleanup());
try{const r=await fetch('data/artifacts.json?v=20261004');if(!r.ok)throw new Error();archive=await r.json();const id=new URLSearchParams(location.search).get('treasure');id?navigate(id,false):gallery();document.body.dataset.ready='true'}catch(e){console.error(e);root.innerHTML='<p class="treasure-loading">珍藏暂时未能读取，请刷新重试。</p>'}
